def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and
                            grid[nx][ny] != 0 and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        stack.append((nx, ny))

            positions = {}
            for x, y in cells:
                positions.setdefault(grid[x][y], []).append((x, y))

            # Nested color regions are ordered by the area of their bounding boxes.
            colors = sorted(
                positions,
                key=lambda color: (
                    (max(x for x, y in positions[color]) -
                     min(x for x, y in positions[color]) + 1) *
                    (max(y for x, y in positions[color]) -
                     min(y for x, y in positions[color]) + 1)
                ),
                reverse=True
            )
            mapping = {color: colors[len(colors) - 1 - i]
                       for i, color in enumerate(colors)}

            for x, y in cells:
                out[x][y] = mapping[grid[x][y]]

    return out
